  'settings.style.input.liquidGlass.section.behavior': '行为组',
  'settings.style.input.liquidGlass.section.extras': 'OpenCodian 增强组',
  'settings.style.input.liquidGlass.shuding.displacementScale': '位移强度',
  'settings.style.input.liquidGlass.shuding.displacementScale.desc': '控制折射位移总量。高一点更明显，低一点更克制',
  'settings.style.input.liquidGlass.shuding.help.displacementScale': '这是最核心的“玻璃感强度”滑块。调高后，输入框后面的内容会被扭曲得更明显；调低后，会更自然、更克制。\n\n如果你只想先调一个参数，通常先调它。',
  'settings.style.input.liquidGlass.shuding.blurAmount': '模糊量',
  'settings.style.input.liquidGlass.shuding.blurAmount.desc': '控制玻璃对后景的轻微柔化。太高会从透明变成发糊',
  'settings.style.input.liquidGlass.shuding.help.blurAmount': '它控制这块玻璃是“清玻璃”还是“磨砂玻璃”。数值越高越柔、越雾；数值越低越清透。\n\n如果你觉得输入框开始发糊、发脏，通常就是这项太高了。',
  'settings.style.input.liquidGlass.shuding.adaptiveSdf': '自适应 SDF',
  'settings.style.input.liquidGlass.shuding.adaptiveSdf.desc': '让折射形状跟着面板真实宽高和圆角走，而不是固定胶囊形',
  'settings.style.input.liquidGlass.shuding.help.adaptiveSdf': '打开后，折射形状会更贴合你现在这个输入框本身的外形。\n\n关闭时会更接近参考版 liquid-glass.js 的默认固定玻璃形。',
  'settings.style.input.liquidGlass.shuding.adaptiveSdfMix': '自适应混合',
  'settings.style.input.liquidGlass.shuding.adaptiveSdfMix.desc': '从旧胶囊轮廓慢慢过渡到真实矩形轮廓。0 更像旧版，1 更贴合面板',
  'settings.style.input.liquidGlass.shuding.help.adaptiveSdfMix': '这项是在“两种形状”之间过渡。`0` 更接近参考版固定玻璃形，`1` 更贴合当前输入框外形。\n\n一般只有在你打开了“自适应 SDF”后，这项才值得调。',
  'settings.style.input.liquidGlass.shuding.rectEdgeRefraction': '矩形边缘折射',
  'settings.style.input.liquidGlass.shuding.rectEdgeRefraction.desc': '把折射集中到边缘窄带，中心尽量保持清晰',
  'settings.style.input.liquidGlass.shuding.help.rectEdgeRefraction': '打开后，折射会更多集中在边缘一圈，中间会更清楚。\n\n这种观感更像“精修过的 UI 玻璃”，不是参考默认那条更纯的折射路线。',
  'settings.style.input.liquidGlass.shuding.rectEdgeRefractionStrength': '边缘折射强度',
  'settings.style.input.liquidGlass.shuding.rectEdgeRefractionStrength.desc': '控制边缘折射有多明显',
  'settings.style.input.liquidGlass.shuding.help.rectEdgeRefractionStrength': '它控制边缘那一圈折射到底有多明显。\n\n只有在你打开“矩形边缘折射”后，这项才会生效。',
  'settings.style.input.liquidGlass.shuding.cornerEnhancement': '角落增强',
  'settings.style.input.liquidGlass.shuding.cornerEnhancement.desc': '让四个角的折射比直边更集中一点',
  'settings.style.input.liquidGlass.shuding.help.cornerEnhancement': '打开后，四个角会比直边更有“玻璃拐角”的感觉。\n\n这是风格增强项，不是参考默认路径的一部分。',
  'settings.style.input.liquidGlass.shuding.cornerEnhancementStrength': '角落增强强度',
  'settings.style.input.liquidGlass.shuding.cornerEnhancementStrength.desc': '控制角落加强的力度',
  'settings.style.input.liquidGlass.shuding.help.cornerEnhancementStrength': '它控制四个角比边更“翘”多少。\n\n只有在你打开“角落增强”后，这项才会生效。',
  'settings.style.input.liquidGlass.shuding.edgeBandWidth': '边缘带宽',
  'settings.style.input.liquidGlass.shuding.edgeBandWidth.desc': '控制边缘折射带有多宽。窄一些更像硬边玻璃',
  'settings.style.input.liquidGlass.shuding.help.edgeBandWidth': '它控制输入框边缘那圈折射到底有多厚。\n\n数值小一点，边缘像一条细玻璃边；数值大一点，被扭曲的范围会更宽。',
  'settings.style.input.liquidGlass.shuding.barrelDistortion': '桶形畸变',
