  'settings.style.input.liquidGlass.shuding.help.barrelDistortion': '打开后，不只是边缘，整块面板包括中间都会带一点“透镜感”。\n\n如果你想更接近参考默认，通常保持关闭。',
  'settings.style.input.liquidGlass.shuding.barrelStrength': '桶形强度',
  'settings.style.input.liquidGlass.shuding.barrelStrength.desc': '控制整体透镜变形的强弱',
  'settings.style.input.liquidGlass.shuding.help.barrelStrength': '它控制整块面板那种“镜头弯曲感”有多强。\n\n只有在你打开“桶形畸变”后，这项才会生效。',
  'settings.style.input.liquidGlass.shuding.topHighlight': '顶部高光',
  'settings.style.input.liquidGlass.shuding.topHighlight.desc': '顶部那条亮线，模拟玻璃上边缘吃到光',
  'settings.style.input.liquidGlass.shuding.help.topHighlight': '打开后，输入框顶部会多一条亮线，看起来像玻璃边缘被灯打到。\n\n它会让输入框更像“设计稿里的玻璃组件”，但不是参考默认视觉。',
  'settings.style.input.liquidGlass.shuding.topHighlightOpacity': '顶部高光强度',
  'settings.style.input.liquidGlass.shuding.topHighlightOpacity.desc': '控制顶部亮线的亮度',
  'settings.style.input.liquidGlass.shuding.help.topHighlightOpacity': '它控制顶部那条亮线有多亮。\n\n只有在你打开“顶部高光”后，这项才会生效。',
