  'settings.style.input.liquidGlass.shuding.help.innerBorder': '打开后，玻璃里面会多一圈细边，让输入框轮廓更清楚。\n\n如果你觉得边界太虚、不够像一个明确组件，可以开它。',
  'settings.style.input.liquidGlass.shuding.innerBorderOpacity': '内框线强度',
