  'settings.style.input.liquidGlass.shuding.help.innerBorderOpacity': '它控制那圈内框线有多显眼。\n\n只有在你打开“内框线”后，这项才会生效。',
  'settings.style.input.liquidGlass.shuding.bottomShadow': '底部阴影线',
