  'settings.style.input.liquidGlass.shuding.insetDepthShadow': '内凹深阴影',
  'settings.style.input.liquidGlass.shuding.insetDepthShadow.desc': '给玻璃内部加一片更大的暗影，偏凹陷感',
  'settings.style.input.liquidGlass.shuding.help.insetDepthShadow': '打开后，玻璃内部会多一片更大的暗影，看起来像稍微往里凹。\n\n如果你想要“悬浮玻璃”，通常不用开；想要“内凹玻璃”再开。',
