  'settings.claudeCode.sandbox.name': '沙箱',
  'settings.claudeCode.sandbox.desc': '控制 Claude Code 是否在操作系统级沙箱中运行。此设置影响沙箱行为（进程隔离），不等于文件系统或网络权限规则。',
  'settings.claudeCode.sandbox.enabled.name': '启用沙箱',
  'settings.claudeCode.sandbox.enabled.desc': '在操作系统级沙箱（如 Linux 上的 bubblewrap）中运行 Claude Code 子进程。插件将此选项传递给 SDK；实际沙箱强制执行由 CLI 二进制文件负责，无法从插件层独立验证。',
  'settings.claudeCode.sandbox.failIfUnavailable.name': '沙箱不可用时失败',
  'settings.claudeCode.sandbox.failIfUnavailable.desc': '启用后，如果无法设置操作系统沙箱，查询将失败。禁用时，如果沙箱设置失败，查询将在无沙箱状态下继续运行。',
  'settings.claudeCode.sandbox.autoAllowBashIfSandboxed.name': '沙箱内自动允许 Bash',
  'settings.claudeCode.sandbox.autoAllowBashIfSandboxed.desc': '当沙箱处于活动状态时，自动批准 Bash 工具调用。仅在启用沙箱时生效。',
  'settings.claudeCode.sandbox.boundaryNotice': '仅为 readback：插件将沙箱选项传递给 SDK，但无法独立验证子进程是否真正运行在操作系统级沙箱中。实际沙箱强制执行（进程隔离、Linux 上的 bubblewrap、macOS 上的平台原生机制）是 SDK/CLI 二进制文件的内部声明——插件层没有 init 事件、工具元数据或 stderr 信号可确认激活状态。当 enabled 为 true 时，SDK 默认将 failIfUnavailable 设为 true，因此如果当前主机缺少沙箱依赖，查询会失败。以下高级子策略已接入 SDK 选项，但受同样的 readback 上限约束。',
  'settings.claudeCode.sandbox.lifecycleNotice': '仅在下一次查询或重启会话时生效。活跃会话不会实时更新。',
  'settings.claudeCode.sandbox.advanced.name': '高级沙箱策略',
  'settings.claudeCode.sandbox.advanced.desc': '细粒度沙箱控制。这些选项传递给 SDK 和 CLI 二进制文件；插件无法独立验证其执行。仅在启用沙箱时生效。',
  'settings.claudeCode.sandbox.excludedCommands.name': '排除命令',
  'settings.claudeCode.sandbox.excludedCommands.desc': '始终绕过沙箱限制的命令（如 docker）。这些命令自动在沙箱外运行，无需模型参与。每行一个命令模式。',
  'settings.claudeCode.sandbox.excludedCommands.placeholder': '例如 docker *',
  'settings.claudeCode.sandbox.allowUnsandboxedCommands.name': '允许非沙箱命令请求',
  'settings.claudeCode.sandbox.allowUnsandboxedCommands.desc': '启用时（SDK 默认），模型可通过 dangerouslyDisableSandbox 请求在沙箱外运行命令，并回退到权限系统。禁用时，逃逸通道被完全封锁——所有命令必须在沙箱内运行（排除命令除外）。建议在严格安全策略下禁用。',
  'settings.claudeCode.sandbox.filesystem.allowWrite.name': '允许写入路径',
  'settings.claudeCode.sandbox.filesystem.allowWrite.desc': '沙箱内命令可写入的额外路径。跨所有设置作用域合并。每行一个路径。支持 /（绝对路径）、~/（主目录）、./ 或无前缀（项目相对路径）。',
  'settings.claudeCode.sandbox.filesystem.allowWrite.placeholder': '例如 /tmp/build',
  'settings.claudeCode.sandbox.filesystem.denyWrite.name': '禁止写入路径',
  'settings.claudeCode.sandbox.filesystem.denyWrite.desc': '沙箱内命令不可写入的路径。跨所有设置作用域合并。每行一个路径。',
  'settings.claudeCode.sandbox.filesystem.denyWrite.placeholder': '例如 /etc',
  'settings.claudeCode.sandbox.filesystem.denyRead.name': '禁止读取路径',
  'settings.claudeCode.sandbox.filesystem.denyRead.desc': '沙箱内命令不可读取的路径。跨所有设置作用域合并。每行一个路径。用于保护 ~/.aws/credentials 等敏感文件。',
  'settings.claudeCode.sandbox.filesystem.denyRead.placeholder': '例如 ~/.aws/credentials',
  'settings.claudeCode.sandbox.network.allowedDomains.name': '允许的域名',
  'settings.claudeCode.sandbox.network.allowedDomains.desc': '沙箱内进程可访问的出站域名。支持通配符（如 *.example.com）。每行一个。',
  'settings.claudeCode.sandbox.network.allowedDomains.placeholder': '例如 github.com',
  'settings.claudeCode.sandbox.network.deniedDomains.name': '禁止的域名',
  'settings.claudeCode.sandbox.network.deniedDomains.desc': '沙箱内进程不可访问的出站域名。优先级高于允许的域名。每行一个。',
  'settings.claudeCode.sandbox.network.deniedDomains.placeholder': '例如 sensitive.example.com',
  'settings.claudeCode.sandbox.enableWeakerNestedSandbox.name': '弱嵌套沙箱',
  'settings.claudeCode.sandbox.enableWeakerNestedSandbox.desc': '在非特权 Docker 环境中启用较弱的沙箱（仅限 Linux/WSL2）。会降低安全性。某些容器环境需要此选项。',
  'settings.claudeCode.sandbox.enableWeakerNetworkIsolation.name': '弱网络隔离',
  'settings.claudeCode.sandbox.enableWeakerNetworkIsolation.desc': '允许在沙箱中访问 macOS TLS 信任服务（com.apple.trustd.agent）。当使用带自定义 CA 的 HTTP 代理时，Go 工具（gh、gcloud、terraform）需要此选项。会打开潜在的数据泄露路径，降低安全性。仅限 macOS。',
  'settings.claudeCode.sandbox.ripgrep.command.name': '自定义 ripgrep 路径',
  'settings.claudeCode.sandbox.ripgrep.command.desc': '沙箱环境使用的自定义 ripgrep 二进制文件的绝对路径。留空则使用自动检测的 rg。',
  'settings.claudeCode.sandbox.ripgrep.command.placeholder': '例如 /usr/local/bin/rg',
  'settings.claudeCode.sandbox.ripgrep.args.name': '自定义 ripgrep 参数',
  'settings.claudeCode.sandbox.ripgrep.args.desc': '自定义 ripgrep 二进制文件的额外参数。每行一个。',
  'settings.claudeCode.sandbox.ripgrep.args.placeholder': '例如 --max-count=100',
  'settings.claudeCode.sandbox.unexposedNotice': '以下 SDK 沙箱字段未在此插件中暴露：allowUnixSockets、allowAllUnixSockets、allowLocalBinding、allowMachLookup、httpProxyPort、socksProxyPort、allowManagedDomainsOnly、allowManagedReadPathsOnly、allowAllManagedReadPathsOnly、filesystem.allowRead、ignoreViolations、bwrapPath、socatPath。它们要么是托管专用（企业级），要么在通用插件中暴露会产生误导，要么过于危险。如需使用，可通过 .claude/settings.json 或 .claude/settings.local.json（可从"运行时"选项卡打开）配置。',
  'settings.claudeCode.sandbox.chatBadge.basic': '沙箱',
  'settings.claudeCode.sandbox.chatBadge.withPolicies': '沙箱（{{count}} 条策略）',
  'settings.claudeCode.sandbox.chatBadge.tooltipHeader': '沙箱策略（readback — 未独立验证）：',
  'settings.claudeCode.sandbox.chatBadge.tooltipReadback': 'Readback：设置已接入 SDK 选项。操作系统级强制执行未独立验证。',
  'settings.claudeCode.sandbox.chatBadge.tooltip.failIfUnavailable': 'failIfUnavailable（不可用时失败）',
  'settings.claudeCode.sandbox.chatBadge.tooltip.autoAllowBash': 'autoAllowBash（自动允许 Bash）',
