  'settings.claudeCode.sandbox.chatBadge.tooltip.fsDenyWrite': 'fs.denyWrite（禁止写入）',
  'settings.claudeCode.sandbox.chatBadge.tooltip.fsDenyRead': 'fs.denyRead（禁止读取）',
  'settings.claudeCode.sandbox.chatBadge.tooltip.netAllowed': 'net.allowed（允许域名）',
  'settings.claudeCode.sandbox.chatBadge.tooltip.netDenied': 'net.denied（禁止域名）',
