  'settings.claudeCode.planModeInstructions.name': '计划模式指令',
  'settings.claudeCode.planModeInstructions.desc': '用于 SDK 计划模式系统提醒的自定义指令。SDK 只会在权限模式为“计划”时使用它们。',
  'settings.claudeCode.planModeInstructions.placeholder': '替换默认计划模式工作流内容...',
  'settings.claudeCode.planModeInstructions.boundaryNotice': '已在诊断 Plan 模式下通过 live 验证：Capability Lab 会把“已保存设置值的 readback 证明”和“同一路径的计划模式行为证明”组合起来看。live proof 使用诊断专用覆盖，因此它本身不直接证明当前保存的具体字符串；它证明的是 planModeInstructions 会到达模型上下文并影响计划模式响应。SDK 的只读前言和 ExitPlanMode 尾部仍属于内部执行细节。',
  'settings.claudeCode.planModeInstructions.lifecycleNotice': '计划模式指令在下一次查询或重启会话后生效。无法更改正在运行中的会话。',
  'settings.claudeCode.systemPrompt.name': 'Claude Code 附加指令',
  'settings.claudeCode.systemPrompt.desc': '附加到 Claude Code 预设系统提示词的自定义指令。这不会替换官方预设——而是在其后追加。留空则仅使用默认预设。',
  'settings.claudeCode.systemPrompt.placeholder': '例如：始终使用 TypeScript。优先函数式编程。',
  'settings.claudeCode.systemPrompt.boundaryNotice': '附加指令会被添加到官方 Claude Code 预设系统提示词之后，不会替换它。SDK 会收到 preset-with-append 结构。Capability Lab 提供两类互补证明：System Prompt Readback Proof 用来确认当前已保存的值是否接入这条路径，System Prompt 实时行为证明则用来确认同一路径会影响一次新的诊断查询。',
  'settings.claudeCode.systemPrompt.lifecycleNotice': '附加指令在下一次查询或重启会话后生效。无法更改正在运行中的会话的附加指令。',
  'settings.claudeCode.outputStyle.name': '输出样式',
  'settings.claudeCode.outputStyle.desc': 'Claude Code 输出样式名称，用于修改系统提示词。官方内置样式包括 Default、Proactive、Explanatory、Learning。你也可以在 .claude/output-styles 或 ~/.claude/output-styles 中创建自定义样式 markdown 文件。留空则使用默认样式。',
  'settings.claudeCode.outputStyle.placeholder': '例如 Explanatory',
  'settings.claudeCode.outputStyle.boundaryNotice': '已对新的诊断查询完成实时验证：Capability Lab 会创建临时自定义输出样式文件，通过 SDK settings.outputStyle 路径选择它，并且只有模型回忆出未出现在用户 prompt 中的 nonce 时才算通过。这不证明活跃会话实时变更，也不验证当前已保存的样式名称是否有效。',
  'settings.claudeCode.outputStyle.lifecycleNotice': 'Claude Code 会在会话启动时读取输出样式。根据官方文档，修改会在 /clear 或新的 Claude Code 会话后生效；已有的活动或恢复会话可能继续使用原先的系统提示词。',
  'settings.claudeCode.model.name': '模型',
  'settings.claudeCode.model.desc': 'Claude Code 会话使用的主模型。尽可能实时应用到当前活动查询。留空则继承 Claude Code 默认值。使用下方的快速选择下拉框从发现的模型中选择。',
  'settings.claudeCode.model.placeholder': 'claude-sonnet-4-5',
  'settings.claudeCode.model.quickSelectName': '快速选择模型',
  'settings.claudeCode.model.quickSelectDesc': '从发现的模型目录中选择。所选值会自动更新上方的模型字段。',
  'settings.claudeCode.fallbackModel.name': '备用模型',
  'settings.claudeCode.fallbackModel.desc': '主模型不可用时使用的备用模型。与主模型不同，备用模型仅在下次查询或重启会话后生效。选项连接和回读已验证；当前 SDK 下自动回退行为尚未验证。',
  'settings.claudeCode.fallbackModel.placeholder': 'claude-haiku-4-5',
  'settings.claudeCode.fallbackModel.boundaryNotice': '仅 readback：此设置保存一个备用模型名称并传递给 SDK。插件已验证该选项到达 SDK 边界（--fallback-model CLI 标志）且同模型校验生效。但自动回退切换行为无法本地验证——需要真实的 API 过载（HTTP 529）信号，无法在本地模拟。请勿将此保存值误解为自动回退生效的证明。修改后需要重启当前会话或开始新的查询。',
  'settings.claudeCode.fallbackModel.quickSelectName': '快速选择备用模型',
  'settings.claudeCode.fallbackModel.quickSelectDesc': '从发现的模型目录中选择备用模型。所选值会自动更新上方的备用模型字段。',
  'settings.claudeCode.fallbackModel.sameModelWarning': '备用模型不能与主模型相同。SDK 会拒绝同模型备用配置。',
  'settings.claudeCode.fallbackModel.clearedByModelChange': '备用模型已清除，因为与新主模型相同。请选择不同的备用模型。',
  'settings.claudeCode.proofStatus.tools': '回读已验证。Allowed Tools 是 pre-allow / auto-approve 快捷方式，不是可用性限制器。运行时证据确认零 enforcement：init catalog 始终未过滤（34 工具），canUseTool 在 SDK query() 模式下无效。如需确定性内置工具过滤，请使用 Restricted Built-in Tools。',
  'settings.claudeCode.proofStatus.limits': '运行时行为已验证。maxTurns 和 maxBudgetUsd enforcement 均已通过实时运行时证明确认（error_max_turns + error_max_budget_usd 信号已观测）。',
  'settings.claudeCode.proofStatus.env': '设置→SDK 映射已验证（回读辅助证据）。实时行为验证（环境变量传播到 Claude/Bash 子进程，Layer 1-4）已在 Capability Lab 中确认。总体能力：已验证（pass）。',
  'settings.claudeCode.proofStatus.mainModel': '实时模型切换已验证。当活跃的持久查询支持 setModel() 时，此处更改模型会立即生效于运行中的查询。否则已保存的模型将应用于下一次查询。这不证明备用模型切换（见备用模型说明）。',
  'settings.claudeCode.proofStatus.fallbackModel': '回读验证。备用模型选项已被 SDK 接受且运行时回读确认（--fallback-model CLI 标志）。SDK 源码确认同模型校验。自动回退切换无法本地验证——回退仅在 API 过载（HTTP 529）时触发，非无效模型错误。无效主模型测试已失效：SDK 在查询边界接受任意模型名称。无法模拟真实 API 过载。阻塞原因：切换行为无法本地证明。',
  'settings.claudeCode.proofStatus.fileCheckpointing': '回读 — 实验性 / 仅诊断。文件 checkpoint 选项已接入 SDK，但 SDK query() 模式下不会产生可用快照（上游 bug #236）。无稳定 rewind UI 或恢复操作。开关和 dry-run 预览在 Debug → Capability Lab 中提供。',
  'settings.claudeCode.modelCatalog.quickSelectPlaceholder': '— 从目录中选择 —',
  'settings.claudeCode.thinking.name': 'Thinking',
  'settings.claudeCode.thinking.desc': '当所选模型支持时，控制 Claude Code 的 thinking 行为。',
