  'settings.claudeCode.effort.name': 'Effort',
  'settings.claudeCode.effort.desc': '传给 SDK options builder 的 Claude Code effort 提示。',
  'settings.claudeCode.effort.low': '低',
  'settings.claudeCode.effort.medium': '中',
