  'settings.claudeCode.effort.xhigh': '特高',
  'settings.claudeCode.effort.max': '最大',
  'settings.claudeCode.additionalDirectories.name': '额外目录',
  'settings.claudeCode.additionalDirectories.desc': '每行一个外部上下文目录。',
  'settings.claudeCode.additionalDirectories.placeholder': '/path/to/extra/context',
  'settings.claudeCode.additionalDirectories.chatBadge.one': '1 个额外目录',
