  'settings.claudeCode.help.proofLabel': '验证状态',
  'settings.claudeCode.toolAliases.name': '工具别名',
  'settings.claudeCode.toolAliases.desc': '将模型发出的工具名映射到规范工具名，在解析前生效。每行一个，格式为 key=value（例如 Fetch=Read）。仅对下一次查询或重启后的会话生效。Readback only — 实际别名解析行为未独立验证。',
  'settings.claudeCode.toolAliases.placeholder': 'Fetch=Read\nSearch=Grep',
  'settings.claudeCode.toolAliases.boundaryNotice': '仅 readback：插件验证 settings→SDK 选项连线。SDK 源码审计（browser-sdk.js）显示 toolAliases 是单向初始化参数，无反馈事件。别名解析发生在 CLI 二进制文件的内部工具执行路径中，且流式 tool_use 块仅暴露解析后的名称，无别名元数据。插件无法区分别名调用与直接规范调用。',
  'settings.claudeCode.toolAliases.lifecycleNotice': '仅在下次查询或重启会话时生效。正在运行中的会话不会实时更新。',
  'settings.claudeCode.askUserQuestionPreviewFormat.name': 'AskUserQuestion 预览格式',
  'settings.claudeCode.askUserQuestionPreviewFormat.desc': '请求 Claude Code SDK 以指定格式为每个 AskUserQuestion 选项包含预览文本。为安全起见，预览以纯文本形式显示在问题卡片中；富 HTML 不会被渲染。仅对下次查询或重启后的会话生效。',
  'settings.claudeCode.askUserQuestionPreviewFormat.none': '无（SDK 默认）',
  'settings.claudeCode.askUserQuestionPreviewFormat.markdown': 'Markdown',
  'settings.claudeCode.askUserQuestionPreviewFormat.html': 'HTML（以纯文本显示）',
  'settings.claudeCode.askUserQuestionPreviewFormat.boundaryNotice': '已通过实时验证（BUILD_ID feature-phase0-capability.202606070354）：所选格式已连入 SDK toolConfig 选项，真实 AskUserQuestion 工具输入会携带 .preview 字段，内容格式与设置一致（Markdown 文本或 HTML 片段）。预览在问题对话框中聚焦或悬停时显示。为安全起见，HTML 预览以纯文本显示（不会解析为富 HTML）。预览是否包含取决于模型——模型不一定会为每个问题都包含预览，但管道和格式差异已验证。',
