  'settings.claudeCode.taskBudget.name': '任务预算',
  'settings.claudeCode.taskBudget.desc': '传给 Claude Code SDK 的可选正整数 token 预算（作为 taskBudget.total）。@alpha — 仅在下一次查询时生效。仅 readback：模型把它当作 pacing 提示，而不是硬性截止。仅接受大于 0 的整数。',
  'settings.claudeCode.taskBudget.placeholder': '50000',
  'settings.claudeCode.taskBudget.boundaryNotice': '仅 readback：插件验证 taskBudget 已接入 SDK 选项并以 --task-budget 传递给 CLI 子进程。CLI 将其作为 output_config.task_budget 连同 task-budgets-2026-03-13 beta header 发送给 API，模型将其用作行为 pacing（非硬性截止）。与 maxTurns（产生 error_max_turns）不同，没有结构化 enforcement 信号。@alpha。',
  'settings.claudeCode.taskBudget.lifecycleNotice': '仅在下次查询或重启会话时生效。无法更改正在运行中的会话的任务预算。',
  'settings.claudeCode.diagnosticStreamMoved.title': '诊断流控制已迁移',
  'settings.claudeCode.diagnosticStreamMoved.desc': 'Hook 事件流、子代理 transcript 转发和进度摘要控制已移至 调试 → 能力实验室。它们仍仅限诊断用途，不影响稳定聊天界面。',
  'settings.claudeCode.enableFileCheckpointing.name': '文件 checkpoint',
  'settings.claudeCode.enableFileCheckpointing.desc': '实验性：启用 SDK 文件 checkpoint 选项。当前 SDK query() 模式不会产生可用快照（上游 bug #236 — 快照创建被 React/Ink UI 路径阻断，在非交互模式下不可用）。无稳定 rewind/恢复 UI。开关和 dry-run 预览：Debug → Capability Lab。',
  'settings.claudeCode.includeHookEvents.name': 'Hook 事件流',
  'settings.claudeCode.includeHookEvents.desc': '将 Claude Code hook 生命周期事件纳入诊断 stream 日志。Hook authoring 已通过 Claude 项目设置提供（扫描/创建/打开 .claude/settings.json）。此开关仅影响诊断流捕获，不控制 hook 激活或稳定界面。',
  'settings.claudeCode.forwardSubagentText.name': '转发子代理 transcript',
  'settings.claudeCode.forwardSubagentText.desc': '要求 SDK 转发子代理文本和 thinking block 到诊断事件流。稳定聊天界面已通过 ToolCallRenderer 和后台任务 UI 渲染 task/subagent 工具；此开关仅影响诊断流捕获。',
  'settings.claudeCode.agentProgressSummaries.name': '子代理进度摘要',
  'settings.claudeCode.agentProgressSummaries.desc': '要求 SDK 发出周期性子代理进度摘要到诊断流。普通聊天在模型调用 task 工具时已显示后台任务状态和完成通知。',
  'settings.claudeCode.promptSuggestions.name': '提示建议',
  'settings.claudeCode.promptSuggestions.desc': '启用后，SDK 可能在每次回复后发出一个预测的后续提示。建议会以可点击标签显示在最后一条 assistant 消息下方，点击后仅插入输入框，不会自动发送。SDK 可能在首轮对话、错误后、计划模式下或因环境变量而不返回建议。',
  'settings.claudeCode.promptSuggestions.stableDesc': '启用后，SDK 可能在每次回复后发出一个预测的后续提示。建议会以可点击标签显示在最后一条 assistant 消息下方，点击后仅插入输入框，不会自动发送。SDK 可能在首轮对话、错误后、计划模式下或因环境变量而不返回建议。',
  'settings.claudeCode.promptSuggestions.boundaryNotice': '已通过 live 验证 (BUILD_ID feature-phase0-capability.202606060953)：提示建议在 Test Vault 普通聊天中端到端观测到。Capability Lab 中的诊断证明按钮仅验证设置→SDK 选项映射（readback 辅助证据）。SDK 可能在首轮对话、错误后、计划模式下或非 Claude 模型时不返回建议。',
  'settings.claudeCode.promptSuggestions.lifecycleNotice': '仅在下次查询或重启会话时生效。无法更改正在运行中的会话的提示建议状态。',
  'settings.claudeCode.debug.name': 'CLI 调试日志',
  'settings.claudeCode.debug.desc': '要求 SDK 在查询执行期间发出 CLI 调试日志。插件将此选项传递给 SDK；CLI 二进制文件是否实际产生调试输出无法从插件层独立验证。',
  'settings.claudeCode.debug.boundaryNotice': '仅回读：此开关启用 CLI 调试日志，但没有独立的可观察效果。除非同时设置调试文件路径，否则调试输出将被静默丢弃。如需可验证的调试输出捕获，请改用 Debug File 设置。',
  'settings.claudeCode.debug.lifecycleNotice': '调试日志设置在下次查询时生效。无法更改正在运行中的会话的调试状态。',
  'settings.claudeCode.strictMcpConfig.name': '严格 MCP 配置',
  'settings.claudeCode.strictMcpConfig.desc': '要求 SDK 将无效的 MCP 服务器配置视为错误而非警告。插件将此选项传递给 SDK；CLI 二进制文件是否实际执行严格验证无法从插件层独立验证。',
  'settings.claudeCode.strictMcpConfig.boundaryNotice': '仅 readback：插件验证 strictMcpConfig 已接入 SDK 选项并以 --strict-mcp-config 传递给 CLI 子进程。实际验证位于编译后的 CLI binary 中；没有结构化信号确认严格验证是否已应用。插件侧 MCP adapter 会静默丢弃结构性 malformed 条目，因此许多 malformed 配置从未到达 CLI。',
  'settings.claudeCode.strictMcpConfig.lifecycleNotice': '严格 MCP 配置设置在下次查询或重启会话时生效。无法更改正在运行中的会话的严格配置状态。',
  'settings.claudeCode.enableContext1mBeta.name': '1M 上下文 Beta',
  'settings.claudeCode.enableContext1mBeta.desc': '向 SDK 请求 \'context-1m-2025-08-07\' beta header 以支持 1M 上下文窗口。插件将此选项传递给 SDK；实际 beta 可用性取决于所选模型和 Anthropic 侧行为。并非所有模型都支持此 beta。',
  'settings.claudeCode.enableContext1mBeta.boundaryNotice': '仅回读：已验证选项接线。设置通过 buildClaudeCodeOptions 传入 SDK options，并以 --betas 标志到达 CLI 子进程。但插件无法验证模型侧 beta 接受、1M 上下文激活或 API 密钥资格。实际可用性取决于所选模型和 Anthropic 侧行为。不暴露通用 beta 管理功能。',
  'settings.claudeCode.enableContext1mBeta.lifecycleNotice': 'Beta 设置在下次查询或重启会话时生效。无法更改正在运行中的会话的 beta 状态。',
  'settings.claudeCode.debugFile.name': '调试文件路径',
  'settings.claudeCode.debugFile.desc': '要求 SDK 将 CLI 调试日志写入指定文件路径。已通过实时验证：真实诊断查询可让 CLI 子进程在共享文件系统上的该路径创建非空文件。设置调试文件路径会隐式启用调试日志，即使上方调试开关为关闭状态。',
  'settings.claudeCode.debugFile.placeholder': '/path/to/claude-debug.log',
  'settings.claudeCode.debugFile.boundaryNotice': '已通过实时验证：CLI 子进程可以在请求的路径创建非空调试文件。插件层仍不会校验路径，也不会代替 CLI 写文件；文件内容和格式仍取决于 SDK/CLI 版本与运行时条件。',
  'settings.claudeCode.debugFile.lifecycleNotice': '调试文件设置在下次查询或重启会话时生效。无法更改正在运行中的会话的调试文件状态。',
  'settings.claudeCode.debugFile.implicitDebugNotice': '设置调试文件路径会隐式启用调试日志，即使上方调试开关为关闭状态。如需关闭调试文件输出，请清空此字段。',

  'settings.claudeCode.jsRuntime.name': 'JavaScript 运行时',
  'settings.claudeCode.jsRuntime.desc': '要求 SDK 为 Claude Code 子进程使用指定的 JavaScript 运行时。自动 表示将选择权交给 SDK。支持 Node.js、Bun 和 Deno 作为运行时选项。插件侧行为未独立验证。',
